 record(){if(this.recorder){this.recorder.stop();return;}if(!window.MediaRecorder){this.notify('当前浏览器不支持视频录制');return;}const mime=['video/webm;codecs=vp9','video/webm;codecs=vp8','video/webm'].find(m=>MediaRecorder.isTypeSupported(m));if(!mime){this.notify('浏览器未提供 WebM 编码器');return;}if(!this.viewfinder)this.toggleViewfinder();this.recordCanvas=document.createElement('canvas');this.recordCanvas.width=1280;this.recordCanvas.height=Math.round(1280/this.captureAspect);this.time=0;this.applyTime();const poster=this.captureImage(640),width=this.recordCanvas.width,height=this.recordCanvas.height;const stream=this.recordCanvas.captureStream(30),chunks=[];this.recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:6000000});this.recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};this.recorder.onstop=async()=>{const duration=Math.max(.1,Math.min(this.duration,this.time));let blob=new Blob(chunks,{type:'video/webm'});stream.getTracks().forEach(t=>t.stop());this.recorder=null;this.recordCanvas=null;this.setPlayback(false);try{blob=await window.LocalMedia.process('finalize',blob,{duration});}catch(error){this.notify('视频已录制，但时长封装失败：'+error.message);}const reader=new FileReader();reader.onload=()=>{window.CanvasApp.createConnected(this.nodeId,[{type:'video',title:'3D 片场录制',video:reader.result,image:poster,width,height}]);this.notify('录制完成，视频已添加到画布');};reader.readAsDataURL(blob);};this.time=0;this.recorder.start(250);this.setPlayback(true);this.notify('正在录制，时间轴结束后自动保存');}
