async function open(id){const target=window.CanvasApp.getState().nodes.find(n=>n.id===id);if(target?.type==='studio'&&(target.studioV2||!target.studio)){if(active)await active.close();return studioV2.open(target);}if(studioV2.current())await studioV2.current().close();if(active?.nodeId===id)return active;if(opening)return opening;if(active)await active.close();const n=window.CanvasApp.getState().nodes.find(n=>n.id===id);if(!n||n.type!=='studio')throw Error('3D 片场节点不存在');opening=(async()=>{try{active=new Studio(n);await active.initialize();return active;}catch(e){active?.notify(e.message);throw e;}finally{opening=null;}})();return opening;}
async function acceptGeneration(job){
 const node=window.CanvasApp.getState().nodes.find(n=>n.id===job.request.nodeId);
 if(!node||node.type!=='studio')throw Error('目标片场已删除；模型仍保留在画布中');
 if(node.studioV2||!node.studio)return applyGeneratedModels(job,{app:window.CanvasApp,assets:window.LocalAssets,store:window.CanvasStore,current:studioV2.current});
 for(const output of job.outputs.filter(o=>o.type==='model'))await loadModel(output.url||output.sourceUrl);
 const current=active?.nodeId===node.id?active:null;
 const result=window.StudioState.applyModels(current?.data||node.studio||window.STUDIO_DEFAULT,job);
 if(current){current.remember();current.data=result.data;await current.rebuild();current.persist();current.renderSelection();current.notify('3D 模型已放入指定状态');}
 else window.CanvasApp.updateNode(node.id,{studio:result.data});
 return {objectIds:result.objectIds,setupId:result.setupId};
}
